// --- API Utility for Translation & Romanization ---
const generateTranslationAndRomanization = async (myanmarText) => {
    const systemPrompt = `You are a specialized Burmese Language expert. Your task is to provide the English Translation and the Burmese Romanization (phonetic transcription) for the given Burmese words.
    1. The input may contain multiple words separated by newlines. Process each one.
    2. The English Translation must be a concise, single-word or short-phrase key (e.g., 'apple' or 'big house') suitable for a dictionary entry. Use lower-case.
    3. The Romanization must be a simple phonetic representation for pronunciation (e.g., 'pann thee').
    4. Output must be a JSON array of objects. Each object must have 'englishKey', 'myanmar', and 'roman' fields.
    5. Do NOT include any markdown, backticks, or explanatory text outside of the JSON object.`;
    
    const userQuery = `Process the following Burmese text (one per line):\n${myanmarText}`;
    const apiKey = ""; 
    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-09-2025:generateContent?key=${apiKey}`;

    const payload = {
        contents: [{ parts: [{ text: userQuery }] }],
        systemInstruction: {
            parts: [{ text: systemPrompt }]
        },
        generationConfig: {
            responseMimeType: "application/json",
            responseSchema: {
                type: "ARRAY",
                items: {
                    type: "OBJECT",
                    properties: {
                        "englishKey": { "type": "STRING", "description": "The concise English translation to be used as a key." },
                        "myanmar": { "type": "STRING", "description": "The original Burmese text." },
                        "roman": { "type": "STRING", "description": "The phonetic Romanization." }
                    },
                    "propertyOrdering": ["englishKey", "myanmar", "roman"]
                }
            }
        }
    };

    for (let i = 0; i < 5; i++) {
        try {
            const response = await fetch(apiUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (response.ok) {
                const result = await response.json();
                const jsonText = result.candidates?.[0]?.content?.parts?.[0]?.text;
                if (jsonText) {
                    const parsedJson = JSON.parse(jsonText);
                    return parsedJson;
                }
                return null;
            } else if (response.status === 429 && i < 4) {
                await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 1000));
            } else {
                console.error("API Error Response:", response);
                return null;
            }
        } catch (error) {
            console.error("Fetch or JSON parse error:", error);
            if (i < 4) {
                 await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 1000));
            } else {
                return null;
            }
        }
    }
    return null;
};
