    const [processedLines, setProcessedLines] = useState([]);
    const [editingId, setEditingId] = useState(null);
    const [editingLineIndex, setEditingLineIndex] = useState(null);
    const [editLineForm, setEditLineForm] = useState({ myanmar: '', roman: '', english: '' });
    const [lessonLineIndex, setLessonLineIndex] = useState(null);
    const [lessonTemplateText, setLessonTemplateText] = useState('');
