const AudioSpeedControl = () => {
    const [rate, setRate] = useState(audioPlaybackRate);
    const [isLoaded, setIsLoaded] = useState(false);

    useEffect(() => {
        const load = async () => {
            try {
                const docSnap = await getDoc(doc(db, AUDIO_SETTINGS_DOC_PATH));
                if (docSnap.exists() && typeof docSnap.data().rate === 'number') {
                    setAudioPlaybackRate(docSnap.data().rate);
                    setRate(docSnap.data().rate);
                }
            } catch (e) {
                console.error("Error loading audio speed:", e);
            }
            setIsLoaded(true);
        };
        load();
        const unsubscribe = subscribeAudioPlaybackRate((newRate) => setRate(newRate));
        return unsubscribe;
    }, []);

    const handleChange = (e) => {
        const percent = Number(e.target.value);
        const newRate = percent / 100;
        setAudioPlaybackRate(newRate);
    };

    const handleCommit = async () => {
        try {
            await setDoc(doc(db, AUDIO_SETTINGS_DOC_PATH), { rate: audioPlaybackRate, updatedAt: Date.now() });
        } catch (e) {
            console.error("Error saving audio speed:", e);
        }
    };

    return (
        <div className="flex items-center gap-3 bg-white rounded-lg shadow-lg px-4 py-2 border-2 border-indigo-200">
            <Volume2 className="w-5 h-5 text-indigo-500 flex-shrink-0" />
            <span className="text-sm font-bold text-gray-600 whitespace-nowrap">Audio Speed</span>
            <input
                type="range"
                min="50"
                max="250"
                step="10"
                value={Math.round(rate * 100)}
                onChange={handleChange}
                onMouseUp={handleCommit}
                onTouchEnd={handleCommit}
                disabled={!isLoaded}
                className="w-32 accent-indigo-600"
            />
            <span className="text-sm font-bold text-indigo-700 w-12 text-right">{Math.round(rate * 100)}%</span>
        </div>
    );
};
const CreatorDashboard = ({ userId, categories, lessons, matchingGames, poems, welcomeQuestions, dictionary, setDictionary }) => {
    const [activeTab, setActiveTab] = useState('lessons');
    const [importStatus, setImportStatus] = useState(null);
    const [pendingImportFile, setPendingImportFile] = useState(null);
    const fileInputRef = useRef(null);

    const handleExport = () => {
        const data = {
            dictionary: Object.values(dictionary),
            categories: categories,
            lessons: lessons.map(({ id, ...rest }) => ({ ...rest, id })),
            matchingGames: matchingGames.map(({ id, ...rest }) => ({ ...rest, id })),
            poems: poems.map(({ id, ...rest }) => ({ ...rest, id })),
            welcomeQuestions: welcomeQuestions || [],
        };
        const jsonString = JSON.stringify(data, null, 2);
        const blob = new Blob([jsonString], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `myanmar_wordcraft_data_${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setImportStatus({ type: 'success', message: `Export လုပ်ပြီးပါပြီ — Dict: ${data.dictionary.length}, Categories: ${data.categories.length}, Lessons: ${data.lessons.length}, Games: ${data.matchingGames.length}, Poems: ${data.poems.length}, Welcome Questions: ${data.welcomeQuestions.length}` });
        setTimeout(() => setImportStatus(null), 5000);
    };

    const onFileChange = (event) => {
        const file = event.target.files[0];
        if (file) {
            setPendingImportFile(file);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };

    const triggerFileInput = () => {
        if (fileInputRef.current) {
            fileInputRef.current.click();
        }
    };

    const runImport = async () => {
        const file = pendingImportFile;
        setPendingImportFile(null);
        if (!file) return;
        if (!userId) {
            setImportStatus({ type: 'error', message: 'Authentication Error. Please reload.' });
            return;
        }

        setImportStatus({ type: 'loading', message: 'ဖိုင်ဖတ်ပြီး data ထည့်နေပါသည်...' });

        const reader = new FileReader();
        reader.onerror = () => {
            setImportStatus({ type: 'error', message: 'ဖိုင်ဖတ်ရာတွင် အမှားယှိနေပါသည်။' });
        };
        reader.onload = async (e) => {
            try {
                if (!e.target.result) throw new Error("ဖိုင်ထဲတွင် content မယှိပါ");
                const data = JSON.parse(e.target.result);
                let importStats = { dict: 0, cats: 0, lessons: 0, games: 0, poems: 0, welcome: 0 };

                if (data.dictionary) {
                    for (const item of data.dictionary) {
                        if (item.englishKey) {
                            await setDoc(doc(db, DICTIONARY_COLLECTION_PATH, item.englishKey), { ...item, createdBy: userId });
                            importStats.dict++;
                        }
                    }
                }
                if (data.categories) {
                    for (const item of data.categories) {
                        if (item.id) {
                            await setDoc(doc(db, CATEGORIES_COLLECTION_PATH, item.id), { ...item, createdBy: userId });
                            importStats.cats++;
                        }
                    }
                }
                if (data.lessons) {
                    for (const item of data.lessons) {
                        const lessonId = item.id || doc(collection(db, LESSONS_COLLECTION_PATH)).id;
                        await setDoc(doc(db, LESSONS_COLLECTION_PATH, lessonId), { ...item, id: lessonId, createdBy: userId });
                        importStats.lessons++;
                    }
                }
                if (data.matchingGames) {
                    for (const item of data.matchingGames) {
                        const gameId = item.id || doc(collection(db, MATCHING_GAMES_COLLECTION_PATH)).id;
                        await setDoc(doc(db, MATCHING_GAMES_COLLECTION_PATH, gameId), { ...item, id: gameId, createdBy: userId });
                        importStats.games++;
                    }
                }
                if (data.poems) {
                    for (const item of data.poems) {
                        const poemId = item.id || doc(collection(db, POEMS_COLLECTION_PATH)).id;
                        await setDoc(doc(db, POEMS_COLLECTION_PATH, poemId), { ...item, id: poemId, createdBy: userId });
                        importStats.poems++;
                    }
                }
                if (data.welcomeQuestions && Array.isArray(data.welcomeQuestions)) {
                    await setDoc(doc(db, WELCOME_QUESTIONS_DOC_PATH), {
                        questions: data.welcomeQuestions,
                        updatedAt: Date.now(),
                        updatedBy: userId
                    });
                    importStats.welcome = data.welcomeQuestions.length;
                }

                setImportStatus({
                    type: 'success',
                    message: `Import အောင်မြင်ပါသည်! Dict: ${importStats.dict}, Categories: ${importStats.cats}, Lessons: ${importStats.lessons}, Games: ${importStats.games}, Poems: ${importStats.poems}, Welcome Questions: ${importStats.welcome}`
                });
                setTimeout(() => setImportStatus(null), 5000);
            } catch (error) {
                console.error("Error importing:", error);
                setImportStatus({ type: 'error', message: "Import မအောင်မြင်ပါ: " + error.message });
            }
        };
        reader.readAsText(file);
    };

    const renderTabContent = () => {
        switch (activeTab) {
            case 'dictionary':
                return <WordProcessor userId={userId} dictionary={dictionary} setDictionary={setDictionary} />;
            case 'lessons':
                return (
                    <div className="space-y-8">
                        <CategoryManager userId={userId} categories={categories} wordMap={dictionary} />
                        <LessonCombinator userId={userId} categories={categories} wordMap={dictionary} />
                    </div>
                );
            case 'match':
    return <MatchingGameCreator userId={userId} dictionary={dictionary} />;
case 'poem':
    return <PoemManager userId={userId} categories={categories} dictionary={dictionary} />;
case 'welcome':
    return <WelcomeQuestionsManager userId={userId} />;
case 'manage':
    return <ManageContentTab lessons={lessons} matchingGames={matchingGames} poems={poems} />;
default:
                return <LessonCombinator userId={userId} categories={categories} wordMap={dictionary} />;
        }
    };

    const tabs = [
    { id: 'lessons', name: 'Lesson', icon: BookOpen },
    { id: 'dictionary', name: 'Word', icon: Database },
    { id: 'match', name: 'Game', icon: Gamepad2 },
    { id: 'poem', name: 'Poem', icon: FileText },
    { id: 'welcome', name: 'Welcome', icon: UserCircle },
    { id: 'manage', name: 'Delete', icon: X }
];

    return (
        <div className="p-4 md:p-8 bg-gray-50 min-h-screen">
            <h1 className="text-4xl font-extrabold text-gray-800 mb-6 border-b-4 border-indigo-500 pb-2">
                <span className="text-indigo-600">Teacher</span> Content Creation Hub
            </h1>
{pendingImportFile && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white p-6 rounded-xl shadow-2xl w-full max-w-sm text-center">
                        <h3 className="text-xl font-bold text-gray-800 mb-2">Data Import လုပ်မှာ သေချာပါသလား?</h3>
                        <p className="text-gray-600 mb-6">ဒီဖိုင်ကို Import လုပ်ရင် လက်ရှိ data တွေနဲ့ merge/overwrite ဖြစ်သွားနိုင်ပါတယ်။</p>
                        <div className="flex gap-3">
                            <button onClick={() => setPendingImportFile(null)} className="flex-1 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl">မလုပ်တော့ပါ</button>
                            <button onClick={runImport} className="flex-1 py-3 bg-indigo-500 text-white font-bold rounded-xl">Import လုပ်မည်</button>
                        </div>
                    </div>
                </div>
            )}
            {importStatus && (
                <div className={`mb-6 p-4 rounded-lg shadow-md flex items-center justify-between animate-fade-in-down ${
                    importStatus.type === 'success' ? 'bg-green-100 border-l-4 border-green-500 text-green-700' :
                    importStatus.type === 'error' ? 'bg-red-100 border-l-4 border-red-500 text-red-700' :
                    'bg-blue-100 border-l-4 border-blue-500 text-blue-700'
                }`}>
                    <div className="flex items-center">
                        {importStatus.type === 'success' && <CheckCircle className="w-6 h-6 mr-3" />}
                        {importStatus.type === 'error' && <AlertCircle className="w-6 h-6 mr-3" />}
                        {importStatus.type === 'loading' && <Loader2 className="w-6 h-6 mr-3 animate-spin" />}
                        <span className="font-bold text-lg">{importStatus.message}</span>
                    </div>
                    <button onClick={() => setImportStatus(null)}><X className="w-5 h-5 opacity-50 hover:opacity-100" /></button>
                </div>
            )}
            
            <div className="flex flex-wrap items-center justify-between mb-8">
                <div className="flex flex-wrap space-x-2 mb-4 md:mb-0">
                    {tabs.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={`p-3 md:px-6 md:py-3 rounded-xl font-bold transition duration-200 shadow-lg flex items-center text-sm md:text-base ${
                                activeTab === tab.id
                                    ? 'bg-indigo-600 text-white ring-4 ring-indigo-300'
                                    : 'bg-white text-gray-700 hover:bg-indigo-50 hover:text-indigo-600'
                            }`}
                        >
                            <tab.icon className="w-5 h-5 mr-2" />
                            {tab.name}
                        </button>
                    ))}
                </div>

                <div className="flex flex-wrap items-center gap-3">
                    <AudioSpeedControl />
                    <input
                        type="file"
                        ref={fileInputRef}
                        accept=".json"
                        style={{ display: 'none' }}
                        onChange={onFileChange}
                    />
                    <button 
                        onClick={triggerFileInput}
                        className="px-4 py-2 bg-yellow-500 text-white rounded-lg font-bold shadow-lg flex items-center hover:bg-yellow-600 transition duration-150"
                    >
                        <Upload className="w-5 h-5 mr-2" /> Import
                    </button>
                    <button
                        onClick={handleExport}
                        className="px-4 py-2 bg-green-500 text-white rounded-lg font-bold shadow-lg flex items-center hover:bg-green-600 transition duration-150"
                    >
                        <Download className="w-5 h-5 mr-2" /> Export
                    </button>
                </div>
            </div>

            {renderTabContent()}
        </div>
    );
};

// --- Role Selection UI ---
const StudentNameEntry = ({ onComplete, setShowRomanization }) => {
    const [name, setName] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState(null);
    const [welcomeQuestions, setWelcomeQuestions] = useState([]);
    const [questionsLoaded, setQuestionsLoaded] = useState(false);
    const [questionIndex, setQuestionIndex] = useState(-1); // -1 = greeting stage, 0..n-1 = question stage
    const [isAsking, setIsAsking] = useState(false);
    const [showLanguagePrompt, setShowLanguagePrompt] = useState(false);
    const [failedAttempts, setFailedAttempts] = useState(0);
    const hasGreetedRef = useRef(false);

    useEffect(() => {
        const load = async () => {
            try {
                const docSnap = await getDoc(doc(db, WELCOME_QUESTIONS_DOC_PATH));
                if (docSnap.exists() && Array.isArray(docSnap.data().questions)) {
                    setWelcomeQuestions(docSnap.data().questions);
                }
            } catch (e) {
                console.error("Error loading welcome questions:", e);
            }
            setQuestionsLoaded(true);
        };
        load();
    }, []);

    const handleSubmit = async () => {
        if (!name.trim() || isLoading) return;
        setIsLoading(true);
        const data = await transliterateNameToMyanmar(name.trim());
        setIsLoading(false);
        if (data && data.myanmar) {
            setResult(data);
        } else {
            setFailedAttempts(prev => prev + 1);
            alert('Could not convert your name. Please try again.');
        }
    };

    const handleSkipEntirely = () => {
        setShowRomanization(false);
        onComplete(name.trim());
    };

    // Auto-play the greeting once, then auto-play each question when questionIndex changes.
    useEffect(() => {
        if (!result || !questionsLoaded) return;

        const run = async () => {
            if (questionIndex === -1) {
                if (hasGreetedRef.current) return;
                hasGreetedRef.current = true;
                setIsAsking(true);
                await playComplexTextKeepRa(`မင်္ဂလာပါ ${result.myanmar}`);
                setIsAsking(false);
            } else if (questionIndex >= 0 && questionIndex < welcomeQuestions.length) {
                setIsAsking(true);
                await playComplexText(welcomeQuestions[questionIndex].myanmar);
                setIsAsking(false);
            }
        };
        run();
    }, [result, questionsLoaded, questionIndex]);

    const handleNext = () => {
        if (isAsking) return;
        if (questionIndex === -1) {
            if (welcomeQuestions.length === 0) {
                setShowLanguagePrompt(true);
            } else {
                setQuestionIndex(0);
            }
        } else if (questionIndex < welcomeQuestions.length - 1) {
            setQuestionIndex(prev => prev + 1);
        } else {
            setShowLanguagePrompt(true);
        }
    };

    const handleReplay = async (text) => {
        if (isAsking) return;
        setIsAsking(true);
        await playComplexText(text);
        setIsAsking(false);
    };

    const isQuestionStage = questionIndex >= 0;
    const currentQuestion = isQuestionStage ? welcomeQuestions[questionIndex] : null;

    if (showLanguagePrompt) {
        return (
            <div className="min-h-screen bg-pink-50 flex items-center justify-center p-4">
                <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center">
                    <UserCircle className="w-16 h-16 text-pink-500 mx-auto mb-4" />
                    <h2 className="text-2xl font-bold text-pink-800 mb-2">How would you like to read?</h2>
                    <p className="text-gray-500 mb-6">You can always switch this later inside any lesson.</p>
                    <div className="space-y-3">
                        <button
                            onClick={() => { setShowRomanization(false); onComplete(name.trim()); }}
                            className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-lg transition duration-200"
                        >
                            Myanmar Script (မြန်မာစာ)
                        </button>
                        <button
                            onClick={() => { setShowRomanization(true); onComplete(name.trim()); }}
                            className="w-full py-4 bg-teal-600 hover:bg-teal-700 text-white font-bold rounded-xl text-lg transition duration-200"
                        >
                            Roman Letters (a, b, c...)
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-pink-50 flex items-center justify-center p-4">
            <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center">
                <UserCircle className="w-16 h-16 text-pink-500 mx-auto mb-4" />

                {!result ? (
                    <>
                        <h2 className="text-2xl font-bold text-pink-800 mb-2">Student Name</h2>
                        <p className="text-gray-500 mb-6">Type your name in English</p>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                            placeholder="e.g. Amara"
                            autoFocus
                            className="w-full p-4 border-2 border-pink-200 rounded-xl mb-4 text-center text-xl font-bold focus:ring-2 focus:ring-pink-500 focus:border-pink-500"
                        />
                        <button
                            onClick={handleSubmit}
                            disabled={isLoading || !name.trim()}
                            className="w-full py-4 bg-pink-600 hover:bg-pink-700 disabled:opacity-50 text-white font-bold rounded-xl text-lg transition duration-200 flex items-center justify-center"
                        >
                            {isLoading && <Loader2 className="w-5 h-5 animate-spin mr-2" />}
                            {isLoading ? 'Converting...' : 'Continue'}
                        </button>
                        {failedAttempts >= 3 && (
                            <button
                                onClick={handleSkipEntirely}
                                className="w-full mt-3 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold rounded-xl text-base transition duration-200"
                            >
                                Skip)
                            </button>
                        )}
                    </>
                ) : !isQuestionStage ? (
                    <>
                        <div
                            onClick={() => handleReplay(`မင်္ဂလာပါ ${result.myanmar}`)}
                            className={`bg-pink-50 border-2 border-pink-300 rounded-xl p-6 mb-6 transition ${isAsking ? 'opacity-70' : 'cursor-pointer hover:bg-pink-100 hover:border-pink-400'}`}
                            title="Tap to hear again"
                        >
                            <p className="text-3xl font-black text-pink-700 mb-1">
                                မင်္ဂလာပါ - {result.myanmar}
                            </p>
                            <p className="text-sm text-gray-500 italic mb-2">
                                mingalarpar - {result.roman}
                            </p>
                            <p className="text-sm text-blue-500 italic">
                                Hello - {name.trim()}
                            </p>
                            <Volume2 className={`w-5 h-5 mx-auto mt-2 ${isAsking ? 'text-pink-300 animate-pulse' : 'text-pink-400'}`} />
                        </div>
                        <button
                            onClick={handleNext}
                            disabled={isAsking}
                            className={`w-full py-4 text-white font-bold rounded-xl text-lg transition duration-200 flex items-center justify-center ${isAsking ? 'bg-gray-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700'}`}
                        >
                            {isAsking ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <ArrowBigRight className="w-5 h-5 mr-2" />}
                            Next
                        </button>
                        <button
                            onClick={() => { setResult(null); hasGreetedRef.current = false; }}
                            className="w-full mt-2 py-2 text-sm text-gray-500 underline"
                        >
                            Edit Name
                        </button>
                    </>
                ) : (
                    <>
                        <p className="text-xs text-gray-400 mb-2">Question {questionIndex + 1} / {welcomeQuestions.length}</p>
                        <div
                            onClick={() => handleReplay(currentQuestion?.myanmar)}
                            className={`bg-indigo-50 border-2 border-indigo-300 rounded-xl p-6 mb-6 transition ${isAsking ? 'opacity-70' : 'cursor-pointer hover:bg-indigo-100 hover:border-indigo-400'}`}
                            title="Tap to hear again"
                        >
                            <p className="text-2xl font-black text-indigo-700 mb-1">
                                {currentQuestion?.myanmar}
                            </p>
                            <p className="text-sm text-gray-500 italic mb-2">
                                {currentQuestion?.roman}
                            </p>
                            <p className="text-sm text-blue-500 italic">
                                {currentQuestion?.english}
                            </p>
                            <Volume2 className={`w-5 h-5 mx-auto mt-2 ${isAsking ? 'text-indigo-300 animate-pulse' : 'text-indigo-400'}`} />
                        </div>
                        <button
                            onClick={handleNext}
                            disabled={isAsking}
                            className={`w-full py-4 text-white font-bold rounded-xl text-lg transition duration-200 flex items-center justify-center ${isAsking ? 'bg-gray-300 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700'}`}
                        >
                            {isAsking ? <Loader2 className="w-5 h-5 animate-spin mr-2" /> : <ArrowBigRight className="w-5 h-5 mr-2" />}
                            Next
                        </button>
                    </>
                )}
            </div>
        </div>
    );
};
