const TeacherAuthScreen = ({ dbPasscode, onAuthenticated, onCancel }) => {
    const [inputCode, setInputCode] = useState('');
    const [error, setError] = useState('');
    const isFirstTime = !dbPasscode;

    const handleSubmit = async () => {
        if (!inputCode.trim()) return;

        if (isFirstTime) {
            try {
                const rolesRef = doc(db, APP_SETTINGS_DOC_PATH);
                await setDoc(rolesRef, { teacherPasscode: inputCode }, { merge: true });
                onAuthenticated();
            } catch (err) {
                setError("Error saving passcode.");
            }
        } else {
            if (inputCode === dbPasscode) {
                onAuthenticated();
            } else {
                setError("မှားယွင်းနေပါသည်။ (Incorrect Passcode)");
            }
        }
    };

    return (
        <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
            <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-8 text-center relative">
                <button onClick={onCancel} className="absolute top-4 left-4 text-gray-400 hover:text-gray-600">
                    <ArrowRight className="w-6 h-6 rotate-180" />
                </button>
                
                <KeyRound className="w-16 h-16 text-indigo-500 mx-auto mb-4" />
                
                <h2 className="text-2xl font-bold text-indigo-800 mb-2">
                    {isFirstTime ? 'Teacher Registration' : 'Teacher Login'}
                </h2>
                <p className="text-gray-600 mb-6">
                    {isFirstTime 
                        ? '' 
                        : ''}
                </p>

                {error && <div className="bg-red-100 text-red-700 p-2 rounded mb-4 font-bold">{error}</div>}

                <input 
                    type="password"
                    value={inputCode}
                    onChange={(e) => setInputCode(e.target.value)}
                    placeholder="Enter Passcode..."
                    className="w-full p-4 border-2 border-indigo-200 rounded-xl mb-4 text-center text-xl font-bold tracking-widest focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                />

                <button 
                    onClick={handleSubmit}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-lg transition duration-200"
                >
                    {isFirstTime ? 'Set Passcode & Register' : 'Login'}
                </button>
            </div>
        </div>
    );
};

export default function MyanmarSpeakingApp({ entryRequest, onExit }) {
    // Arrives as entryRequest={ studentName } when opened via TutoringApp's
    // Assign Lesson / Continue flow — in that case we skip straight to the
    // student view under their real name instead of asking again, and start
    // the minutes timer immediately (same idea as MyanmarReaderApp.jsx's
    // deepLinkStudentName).
    const deepLinkStudentName = entryRequest?.studentName || null;

    const [userId, setUserId] = useState(null);
    const [isAuthReady, setIsAuthReady] = useState(false);

    // Roles: null (selection screen), 'student', 'teacher_auth', 'teacher'
    const [activeRole, setActiveRole] = useState(() => deepLinkStudentName ? 'student' : null);
    const [dbTeacherPasscode, setDbTeacherPasscode] = useState(null);
    const [studentName, setStudentName] = useState(() => deepLinkStudentName || '');

    const [dictionary, setDictionary] = useState({});
    const [categories, setCategories] = useState([]);
    const [lessons, setLessons] = useState([]);
    const [matchingGames, setMatchingGames] = useState([]);
    const [poems, setPoems] = useState([]);
    const [welcomeQuestions, setWelcomeQuestions] = useState([]);
    const [showRomanization, setShowRomanization] = useState(false);
    const [studySessionStart, setStudySessionStart] = useState(() => deepLinkStudentName ? Date.now() : null);

    // Live "who's online" roster, shown to both teacher and student — same
    // pattern as MyanmarReaderApp.jsx's READER_ROSTER_PATH.
    const [onlineStudents, setOnlineStudents] = useState([]);
    const [showOnlinePanel, setShowOnlinePanel] = useState(false);
    const [nowForOnlineCheck, setNowForOnlineCheck] = useState(Date.now());
    const minutesWrittenRef = useRef(0);
    const lastActivityRef = useRef(Date.now());
    const activeMsRef = useRef(0);
    const appliedDeepLinkRef = useRef(null);

    // This component mounts once when the whole SPA loads (hidden, per
    // App.jsx's "keep everything mounted" design) — at that point
    // entryRequest is still null, so the lazy useState initializers above
    // never see a real studentName. This effect catches it once it actually
    // arrives (when the student clicks Continue), so they land straight in
    // the student view under their own name instead of the manual
    // role-selection / name-entry screens.
    useEffect(() => {
        if (deepLinkStudentName && appliedDeepLinkRef.current !== deepLinkStudentName) {
            appliedDeepLinkRef.current = deepLinkStudentName;
            setStudentName(deepLinkStudentName);
            setActiveRole('student');
            setStudySessionStart(Date.now());
        }
    }, [deepLinkStudentName]);

    useEffect(() => {
        initializeAuth();
        const unsubscribeAuth = onAuthStateChanged(auth, async (user) => {
            if (user) {
                setUserId(user.uid);
            } else {
                setUserId(null);
            }
            setIsAuthReady(true);
        });
        return () => unsubscribeAuth();
    }, []); 

    useEffect(() => {
        if (!isAuthReady || !userId) return;
        
        const qDictionary = query(collection(db, DICTIONARY_COLLECTION_PATH));
        const unsubscribeDictionary = onSnapshot(qDictionary, (snapshot) => {
            const dictionaryMap = {};
            snapshot.docs.forEach(doc => {
                dictionaryMap[doc.id] = { id: doc.id, ...doc.data() };
            });
            setDictionary(dictionaryMap);
        });
        const qCategories = query(collection(db, CATEGORIES_COLLECTION_PATH));
        const unsubscribeCategories = onSnapshot(qCategories, (snapshot) => {
            const categoryList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setCategories(categoryList);
        });
        const qLessons = query(collection(db, LESSONS_COLLECTION_PATH));
        const unsubscribeLessons = onSnapshot(qLessons, (snapshot) => {
            const lessonList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setLessons(lessonList);
        });
        const qMatchingGames = query(collection(db, MATCHING_GAMES_COLLECTION_PATH));
        const unsubscribeMatchingGames = onSnapshot(qMatchingGames, (snapshot) => {
            const gameList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setMatchingGames(gameList);
        });
        const qPoems = query(collection(db, POEMS_COLLECTION_PATH));
        const unsubscribePoems = onSnapshot(qPoems, (snapshot) => {
            const poemList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setPoems(poemList);
        });
        const unsubscribeWelcomeQuestions = onSnapshot(doc(db, WELCOME_QUESTIONS_DOC_PATH), (docSnap) => {
            setWelcomeQuestions(docSnap.exists() && Array.isArray(docSnap.data().questions) ? docSnap.data().questions : []);
        });
        const unsubscribeAudioSettings = onSnapshot(doc(db, AUDIO_SETTINGS_DOC_PATH), (docSnap) => {
            if (docSnap.exists() && typeof docSnap.data().rate === 'number') {
                setAudioPlaybackRate(docSnap.data().rate);
            }
        });
        return () => {
            unsubscribeDictionary();
            unsubscribeCategories();
            unsubscribeLessons();
            unsubscribeMatchingGames();
            unsubscribePoems();
            unsubscribeWelcomeQuestions();
            unsubscribeAudioSettings();
        };
    }, [isAuthReady, userId]);

    // Presence + minutes tracking, combined so both respect idle time: if the
    // student hasn't touched/clicked/typed anything for IDLE_MS, they're
    // marked offline and minutes stop accumulating (being "in" the app with
    // an untouched screen shouldn't count as studying or being online).
    // Activity resumes both the instant they interact again.
    useEffect(() => {
        if (activeRole !== 'student' || !studentName) return;
        const IDLE_MS = 2 * 60 * 1000; // 2 minutes with no touch/click/key
        const TICK_MS = 15000;
        const rosterRef = doc(db, ROSTER_PATH, sanitizeSpeakingKey(studentName));
        let isIdle = false;

        const markActivity = () => { lastActivityRef.current = Date.now(); };
        const activityEvents = ['touchstart', 'mousedown', 'keydown', 'scroll'];
        activityEvents.forEach(evt => window.addEventListener(evt, markActivity, { passive: true }));

        const flushMinutes = () => {
            const activeMinutes = Math.floor(activeMsRef.current / 60000);
            const delta = activeMinutes - minutesWrittenRef.current;
            if (delta <= 0) return;
            minutesWrittenRef.current = activeMinutes;
            const todayKey = new Date().toISOString().split('T')[0];
            const minutesRef = doc(db, DAILY_MINUTES_PATH, `${sanitizeSpeakingKey(studentName)}_${todayKey}`);
            setDoc(minutesRef, { studentName, date: todayKey, minutes: increment(delta) }, { merge: true }).catch(e => console.error('Minutes flush error:', e));
        };

        const goOffline = () => { updateDoc(rosterRef, { isOnline: false, lastSeen: serverTimestamp() }).catch(() => {}); };

        const tick = () => {
            const idleNow = (Date.now() - lastActivityRef.current) > IDLE_MS;
            if (idleNow) {
                if (!isIdle) { isIdle = true; goOffline(); }
                return; // no ping, no minutes while idle
            }
            isIdle = false;
            setDoc(rosterRef, { studentName, isOnline: true, lastSeen: serverTimestamp() }, { merge: true }).catch(() => {});
            activeMsRef.current += TICK_MS;
            flushMinutes();
        };
        tick();
        const interval = setInterval(tick, TICK_MS);
        window.addEventListener('beforeunload', goOffline);
        return () => {
            clearInterval(interval);
            activityEvents.forEach(evt => window.removeEventListener(evt, markActivity));
            window.removeEventListener('beforeunload', goOffline);
            flushMinutes();
            goOffline();
        };
    }, [studentName, activeRole]);

    // Full live roster — same list feeds both the teacher's panel and every
    // student's own "who else is online" panel.
    useEffect(() => {
        const unsub = onSnapshot(collection(db, ROSTER_PATH), (snap) => {
            setOnlineStudents(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        }, e => console.error('Myanmar Speaking roster listen error:', e));
        return () => unsub();
    }, []);

    // Ticks every 30s so "online" (last seen within 5 min) stays current
    // without a page reload.
    useEffect(() => {
        const interval = setInterval(() => setNowForOnlineCheck(Date.now()), 30000);
        return () => clearInterval(interval);
    }, []);

    const FIVE_MIN_MS = 5 * 60 * 1000;
    const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
    const isRosterEntryOnline = (s) => {
        const lastSeenMs = s.lastSeen?.toMillis ? s.lastSeen.toMillis() : (s.lastSeen?.seconds ? s.lastSeen.seconds * 1000 : 0);
        return lastSeenMs > 0 && (nowForOnlineCheck - lastSeenMs) < FIVE_MIN_MS;
    };
    const weeklyRosterList = onlineStudents
        .filter(s => {
            const lastSeenMs = s.lastSeen?.toMillis ? s.lastSeen.toMillis() : (s.lastSeen?.seconds ? s.lastSeen.seconds * 1000 : 0);
            return lastSeenMs > 0 && (nowForOnlineCheck - lastSeenMs) < ONE_WEEK_MS;
        })
        .map(s => ({ ...s, _isOnlineNow: isRosterEntryOnline(s) }))
        .sort((a, b) => {
            if (a._isOnlineNow !== b._isOnlineNow) return b._isOnlineNow ? 1 : -1;
            const aMs = a.lastSeen?.toMillis ? a.lastSeen.toMillis() : 0;
            const bMs = b.lastSeen?.toMillis ? b.lastSeen.toMillis() : 0;
            return bMs - aMs;
        });
    const onlineCount = onlineStudents.filter(isRosterEntryOnline).length;

    const handleSelectTeacher = async () => {
        setIsAuthReady(false);
        try {
            const rolesRef = doc(db, APP_SETTINGS_DOC_PATH);
            const rolesDoc = await getDoc(rolesRef);
            if (rolesDoc.exists() && rolesDoc.data().teacherPasscode) {
                setDbTeacherPasscode(rolesDoc.data().teacherPasscode);
            } else {
                setDbTeacherPasscode(null);
            }
            setActiveRole('teacher_auth');
        } catch (e) {
            console.error("Error fetching roles", e);
        }
        setIsAuthReady(true);
    };

    if (!isAuthReady) return <LoadingSpinner />;

    if (activeRole === null) {
        return <RoleSelection 
            onSelectStudent={() => { setStudySessionStart(Date.now()); setActiveRole('student_name'); }} 
            onSelectTeacher={handleSelectTeacher} 
        />;
    }

    if (activeRole === 'student_name') {
        return <StudentNameEntry
            onComplete={(enteredName) => { if (enteredName) setStudentName(enteredName); setActiveRole('student'); }}
            setShowRomanization={setShowRomanization}
        />;
    }

    if (activeRole === 'teacher_auth') {
        return <TeacherAuthScreen 
            dbPasscode={dbTeacherPasscode} 
            onAuthenticated={() => setActiveRole('teacher')}
            onCancel={() => setActiveRole(null)}
        />;
    }

    return (
        <div className={COLOR_PALETTE.text}>
            <header className="p-3 bg-indigo-700 text-white shadow-xl flex justify-between items-center sticky top-0 z-10">
                <div className="font-extrabold text-xl tracking-wider flex items-center cursor-pointer" onClick={() => { setActiveRole(null); setStudySessionStart(null); }}>
                    <ArrowRight className="w-5 h-5 mr-2 rotate-180 opacity-50 hover:opacity-100" />
                    Myanmar <span className="text-yellow-400 ml-1">WordCraft</span>
                </div>
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => setShowOnlinePanel(true)}
                        className="flex items-center gap-1 text-sm font-bold bg-indigo-800 px-3 py-1 rounded-full border border-indigo-500 hover:bg-indigo-900"
                    >
                        <span className="w-2 h-2 bg-emerald-400 rounded-full inline-block"></span>{onlineCount} online
                    </button>
                    <div className="text-sm font-bold bg-indigo-800 px-3 py-1 rounded-full border border-indigo-500">
                    {activeRole === 'teacher' ? '👩‍🏫 Teacher Mode' : '👩‍🎓 Student Mode'}
                    </div>
                </div>
            </header>

            {/* Online Students panel — same view for teacher and every student */}
            {showOnlinePanel && (
                <div className="fixed inset-0 z-[9950] bg-black/40 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setShowOnlinePanel(false)}>
                    <div className="bg-white rounded-3xl shadow-2xl max-w-lg w-full max-h-[80vh] overflow-y-auto p-6" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-bold text-gray-800">🗣️ Students {onlineCount > 0 && <span className="text-emerald-600">({onlineCount} online)</span>}</h2>
                            <button onClick={() => setShowOnlinePanel(false)} className="text-gray-400 hover:text-gray-700"><X size={22}/></button>
                        </div>
                        <p className="text-xs text-gray-400 mb-3">Showing everyone active in the last 7 days.</p>
                        <div className="space-y-2">
                            {weeklyRosterList.map(s => (
                                <div key={s.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl border border-gray-100">
                                    <div className="flex items-center gap-2">
                                        <span className={`w-2.5 h-2.5 rounded-full flex-shrink-0 ${s._isOnlineNow ? 'bg-emerald-500' : 'bg-gray-300'}`}></span>
                                        <span className="font-bold text-gray-800">{s.studentName}</span>
                                    </div>
                                    <span className="text-xs text-gray-400">{s._isOnlineNow ? 'Online now' : 'Active this week'}</span>
                                </div>
                            ))}
                            {weeklyRosterList.length === 0 && <p className="text-center text-gray-400 py-6">No students active this week yet.</p>}
                        </div>
                    </div>
                </div>
            )}

            {(activeRole === 'teacher' || activeRole === 'student_preview') && (
                <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-50">
                    {activeRole === 'teacher' ? (
                        <button
                            onClick={() => setActiveRole('student_preview')}
                            className="bg-yellow-400 text-black px-5 py-3 rounded-full font-bold shadow-2xl hover:bg-yellow-300 hover:scale-105 transition flex items-center gap-2"
                        >
                            👁 Preview as Student
                        </button>
                    ) : (
                        <button
                            onClick={() => setActiveRole('teacher')}
                            className="bg-green-400 text-black px-5 py-3 rounded-full font-bold shadow-2xl hover:bg-green-300 hover:scale-105 transition flex items-center gap-2"
                        >
                            ↩ Back to Teacher
                        </button>
                    )}
                </div>
            )}
            
            {activeRole === 'teacher' ? (
    <CreatorDashboard 
    userId={userId} 
    categories={categories} 
    lessons={lessons}
    matchingGames={matchingGames}
    poems={poems}
    welcomeQuestions={welcomeQuestions}
    dictionary={dictionary}
    setDictionary={setDictionary} 
/>
) : (
    <StudentDashboard 
        lessons={lessons} 
        matchingGames={matchingGames} 
        showRomanization={showRomanization}
        setShowRomanization={setShowRomanization}
        dictionary={dictionary} 
        categories={categories}
        studySessionStart={studySessionStart}
    />
)}
        </div>
    );
}